import { sha256Bytes } from '@forgeax/engine-types';

export const UE_DEFAULT_WATER_BRUSH_CURVE_ENGINE_VERSION = 'UE 5.8.1 CL 56057345' as const;
export const UE_DEFAULT_WATER_BRUSH_CURVE_SHA256 =
  '29f4387d555b6103e194420a09414a03daafd29638982735b843566ca06ba8b4' as const;

// Exported by UE Editor Python from /Water/Curves/FloatCurve.FloatCurve at i / 255,
// then quantized to the little-endian IEEE 754 binary16 values uploaded to R16f.
const DEFAULT_CURVE_R16F_HEX = [
  '',
].join('');

export function waterBrushDefaultCurveR16fBytes(): Uint8Array {
  const bytes = Uint8Array.from({ length: DEFAULT_CURVE_R16F_HEX.length / 2 }, (_, index) =>
    Number.parseInt(DEFAULT_CURVE_R16F_HEX.slice(index * 2, index * 2 + 2), 16),
  );
  if (bytes.byteLength !== 512 || sha256Bytes(bytes) !== UE_DEFAULT_WATER_BRUSH_CURVE_SHA256) {
    throw new Error('UE 5.8.1 default Water Brush curve fixture digest mismatch');
  }
  return bytes;
}
